			cmd := exec.CommandContext(t.Context(), "/bin/sh", "-c",
				fn+"PCI_BRIDGES=\"$1\"; qemu_data_nic \"$2\" \"$3\"",
				"chr-launch-test", fmt.Sprint(tc.pciBridges), fmt.Sprint(tc.index), mac)
			out, err := cmd.CombinedOutput()
